settings.cardCss:
.card {
   width: 100%;
   height: 100%;
   border: 1px solid #E0E0E0;
   box-sizing: border-box;
   background-color: #ffffff;
   border-radius: 8px;
   box-shadow: 0 4px 8px rgba(0,0,0,0.1);
}

.card .content {
   padding: 20px 10px;
   display: flex;
   flex-direction: column;
   align-items: center;
   justify-content: center;
   height: 100%;
   box-sizing: border-box;
}

.card .title {
    font-size: 1.2em;
    font-weight: 600;
    margin-bottom: 10px;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.card .value {
    font-weight: 700;
    font-size: 3.5em;
    line-height: 1.1em;
    text-align: center;
    color: #333333;
}

.card .unit {
    font-size: 0.4em;
    color: #888888;
    font-weight: 500;
}

